/**
 * Japan-Readiness & Trust Score (0–100) — TypeScript port of backend/app/domain/partner_trust.py.
 *
 * Same contract: pure function of a partner record, decimal arithmetic in Python's default
 * context (28 significant digits, half-even) with ROUND_HALF_UP to 0.1 per component, the
 * total is the sum of the rounded components, and hard gates cap it. Scores and the
 * inputs hash must equal the Python implementation's; test/partner-trust-parity.test.ts
 * checks every fixture against output generated by the Python code.
 *
 * Weights (sum 100): MCA 15 · GSTN 15 · litigation 10 · ISO 10 · credit 15 · delivery 20 · cross-border 15
 */

import { createHash } from 'node:crypto'
import DecimalJs from 'decimal.js'

const Dec = DecimalJs.clone({ precision: 28, rounding: DecimalJs.ROUND_HALF_EVEN })
type Dec = InstanceType<typeof Dec>
const D = (v: string | number) => new Dec(v)
const ZERO = D(0)
const ONE = D(1)

export const SCORING_VERSION = 'trust-v1'
export const BLOCKED_CAP = D(25)
export const LITIGATION_CAP = D(49)
const TIERS: [Dec, Tier][] = [[D(80), 'japan_ready'], [D(65), 'conditional'], [D(50), 'high_friction']]

export const DISCLOSURE =
  'Advisory screening only. Simulated fixture data is not a registry verification; confirm MCA, ' +
  'GSTN, litigation and credit status against primary sources before any commitment.'
const MCA_PORTAL = 'https://www.mca.gov.in/'
const GST_PORTAL = 'https://services.gst.gov.in/services/searchtp'

export const SECTORS = ['auto', 'electronics', 'fmcg', 'robotics', 'chemicals'] as const
export type Sector = (typeof SECTORS)[number]
export type Tier = 'japan_ready' | 'conditional' | 'high_friction' | 'not_recommended' | 'blocked'
type Pct = string // exact decimal text, as stored

export type PartnerRecord = {
  id: string
  partner_name: string
  record_source: 'simulated_fixture' | 'registry_mock' | 'registry_verified'
  sector: Sector
  state: string
  city: string | null
  partner_type: 'distributor' | 'supplier' | 'jv_partner' | 'contract_manufacturer'
  mca_registration_no: string
  gstin: string
  registered_address: string
  incorporated_on: string | null
  mca_compliance: { status: string; annual_filings_on_time_last3: number; last_annual_return_fy: string | null }
  gst_compliance: { status: string; returns_on_time_last12: number; last_return_period: string | null }
  director_history: { name: string; din: string; role: string; appointed_on: string; ceased_on: string | null }[]
  litigation: { forum: string; case_type: string; status: string; severity: string; summary: string; reference: string }[]
  financial_solvency_score: Pct | null
  credit_rating: { agency: string; band: 'low' | 'moderate' | 'high' | 'unrated'; as_of: string | null }
  iso_certifications: {
    standard: 'ISO 9001' | 'ISO 14001'
    status: 'verified' | 'claimed_unverified' | 'expired'
    certificate_no: string | null
    certification_body: string | null
    valid_until: string | null
  }[]
  operations: {
    otd_monthly_pct: Pct[]
    fulfillment_accuracy_pct: Pct
    client_retention_pct: Pct
    foreign_principal_satisfaction_pct: Pct
    sla_compliance_pct: Pct
  }
  cross_border: { contracts_total: number; contracts_fulfilled: number; japanese_principals: number }
  data_as_of: string
}

export type ScoreComponent = { key: string; label: string; points: string; max_points: string; reasons: string[] }
export type TrustFlag = { level: 'block' | 'warn' | 'info'; code: string; message: string }
export type TrustAudit = {
  partner_id: string
  partner_name: string
  record_source: PartnerRecord['record_source']
  simulated: boolean
  score: string
  uncapped_score: string
  tier: Tier
  components: ScoreComponent[]
  flags: TrustFlag[]
  otd_trailing_pct: string
  evidence: { label: string; url: string; note: string }[]
  scoring_version: string
  inputs_hash: string
  computed_at: string
  disclosure: string
  record: PartnerRecord
}

// ── Normalising a database row into the record contract ─────────────────────

const pct = (v: unknown): Pct => {
  if (typeof v !== 'string' && typeof v !== 'number') throw new Error('expected a decimal value')
  return String(v)
}
const opt = <T>(v: T | undefined | null): T | null => (v === undefined ? null : v)

/** Builds the exact record shape from a partner_registry row (extra columns dropped, optionals filled). */
export function toRecord(row: Record<string, any>): PartnerRecord {
  const ops = row.operations
  return {
    id: row.id,
    partner_name: row.partner_name,
    record_source: row.record_source,
    sector: row.sector,
    state: row.state,
    city: opt(row.city),
    partner_type: row.partner_type,
    mca_registration_no: row.mca_registration_no,
    gstin: row.gstin,
    registered_address: row.registered_address,
    incorporated_on: opt(row.incorporated_on),
    mca_compliance: {
      status: row.mca_compliance.status,
      annual_filings_on_time_last3: row.mca_compliance.annual_filings_on_time_last3,
      last_annual_return_fy: opt(row.mca_compliance.last_annual_return_fy),
    },
    gst_compliance: {
      status: row.gst_compliance.status,
      returns_on_time_last12: row.gst_compliance.returns_on_time_last12,
      last_return_period: opt(row.gst_compliance.last_return_period),
    },
    director_history: (row.director_history ?? []).map((d: any) => ({
      name: d.name, din: d.din, role: d.role, appointed_on: d.appointed_on, ceased_on: opt(d.ceased_on),
    })),
    litigation: (row.litigation ?? []).map((c: any) => ({
      forum: c.forum, case_type: c.case_type, status: c.status, severity: c.severity, summary: c.summary, reference: c.reference,
    })),
    financial_solvency_score: row.financial_solvency_score == null ? null : pct(row.financial_solvency_score),
    credit_rating: { agency: row.credit_rating.agency, band: row.credit_rating.band, as_of: opt(row.credit_rating.as_of) },
    iso_certifications: (row.iso_certifications ?? []).map((c: any) => ({
      standard: c.standard, status: c.status, certificate_no: opt(c.certificate_no),
      certification_body: opt(c.certification_body), valid_until: opt(c.valid_until),
    })),
    operations: {
      otd_monthly_pct: ops.otd_monthly_pct.map(pct),
      fulfillment_accuracy_pct: pct(ops.fulfillment_accuracy_pct),
      client_retention_pct: pct(ops.client_retention_pct),
      foreign_principal_satisfaction_pct: pct(ops.foreign_principal_satisfaction_pct),
      sla_compliance_pct: pct(ops.sla_compliance_pct),
    },
    cross_border: {
      contracts_total: row.cross_border.contracts_total,
      contracts_fulfilled: row.cross_border.contracts_fulfilled,
      japanese_principals: row.cross_border.japanese_principals,
    },
    data_as_of: row.data_as_of,
  }
}

// ── Arithmetic helpers ───────────────────────────────────────────────────────

const q = (x: Dec) => x.toDecimalPlaces(1, Dec.ROUND_HALF_UP)
const q1 = (x: Dec) => q(x).toFixed(1) // Python str() of a value quantised to 0.1
const int = (x: Dec) => x.toFixed(0) // Python str() of an integral Decimal

function scale(value: Dec, floor: Dec, ceiling: Dec): Dec {
  if (value.lte(floor)) return ZERO
  if (value.gte(ceiling)) return ONE
  return value.minus(floor).div(ceiling.minus(floor))
}

export function otdTrailing(p: PartnerRecord): Dec {
  const months = p.operations.otd_monthly_pct.map(D)
  return q(months.reduce((a, b) => a.plus(b), ZERO).div(months.length))
}

// ── Inputs hash (identical to Python's json.dumps(sort_keys, ensure_ascii) over the record) ──

const DECIMAL_PATHS = new Set([
  'financial_solvency_score',
  'operations.otd_monthly_pct',
  'operations.fulfillment_accuracy_pct',
  'operations.client_retention_pct',
  'operations.foreign_principal_satisfaction_pct',
  'operations.sla_compliance_pct',
])

function canonical(value: unknown, path: string): unknown {
  if (value === null) return null
  if (DECIMAL_PATHS.has(path) && !Array.isArray(value)) {
    const text = D(value as string).toFixed() // normalised: no trailing zeros, no exponent
    return text === '-0' ? '0' : text
  }
  if (Array.isArray(value)) return value.map((v) => canonical(v, path))
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {}
    for (const key of Object.keys(value as object).sort()) {
      out[key] = canonical((value as Record<string, unknown>)[key], path ? `${path}.${key}` : key)
    }
    return out
  }
  return value
}

const asciiJson = (v: unknown) =>
  JSON.stringify(v).replace(/[\u007f-￿]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'))

export function inputsHash(p: PartnerRecord): string {
  const text = asciiJson(canonical(p, ''))
  return createHash('sha256').update(`${SCORING_VERSION}\n${text}`).digest('hex')
}

// ── Components ───────────────────────────────────────────────────────────────

const human = (s: string) => s.replaceAll('_', ' ')
type Component = { key: string; label: string; points: Dec; max: number; reasons: string[] }

function mca(p: PartnerRecord, flags: TrustFlag[]): Component {
  const m = p.mca_compliance
  const base = D(({ active: 9, active_non_compliant: 3 } as Record<string, number>)[m.status] ?? 0)
  const reasons = [`MCA status: ${human(m.status)} (${int(base)} pts)`]
  if (m.status === 'strike_off' || m.status === 'under_liquidation') {
    flags.push({ level: 'block', code: 'mca_not_active', message: `Company is ${human(m.status)} on MCA records.` })
  } else if (m.status === 'dormant') {
    flags.push({ level: 'warn', code: 'mca_dormant', message: 'Company is marked dormant on MCA records.' })
  } else if (m.status === 'active_non_compliant') {
    flags.push({ level: 'warn', code: 'mca_non_compliant', message: 'Active but non-compliant with MCA annual filings.' })
  }
  const filings = D(2).times(m.annual_filings_on_time_last3)
  reasons.push(`Annual filings on time in ${m.annual_filings_on_time_last3}/3 recent years (${int(filings)} pts)`)
  return { key: 'mca', label: 'MCA compliance & filing status', points: q(base.plus(filings)), max: 15, reasons }
}

function gst(p: PartnerRecord, flags: TrustFlag[]): Component {
  const g = p.gst_compliance
  const base = g.status === 'active' ? D(5) : ZERO
  if (g.status === 'cancelled') flags.push({ level: 'block', code: 'gst_cancelled', message: 'GST registration is cancelled.' })
  else if (g.status === 'suspended') flags.push({ level: 'warn', code: 'gst_suspended', message: 'GST registration is suspended.' })
  const regular = D(10).times(g.returns_on_time_last12).div(12)
  if (g.returns_on_time_last12 < 10) {
    flags.push({ level: 'warn', code: 'gst_irregular', message: `Only ${g.returns_on_time_last12}/12 GST returns filed on time.` })
  }
  return {
    key: 'gst', label: 'GSTN filing regularity', points: q(base.plus(regular)), max: 15,
    reasons: [`GST registration ${g.status} (${int(base)} pts)`, `${g.returns_on_time_last12}/12 returns on time (${q1(regular)} pts)`],
  }
}

function litigation(p: PartnerRecord, flags: TrustFlag[]): Component {
  const pending = p.litigation.filter((c) => c.status === 'pending')
  const major = pending.filter((c) => c.severity === 'major' && (c.case_type === 'tax' || c.case_type === 'corporate'))
  if (major.length) {
    for (const c of major) {
      flags.push({ level: 'block', code: 'litigation_major', message: `Pending major ${c.case_type} matter: ${c.summary} (${c.reference}).` })
    }
    return { key: 'litigation', label: 'Litigation exposure', points: ZERO, max: 10, reasons: [`${major.length} pending major tax/corporate matter(s) (0 pts)`] }
  }
  const deduction = Dec.min(D(2).times(pending.length), D(6))
  if (pending.length) flags.push({ level: 'warn', code: 'litigation_pending', message: `${pending.length} pending minor/commercial matter(s).` })
  const reasons = pending.length ? [`${pending.length} pending minor matter(s) (−${int(deduction)} pts)`] : ['No pending litigation (10 pts)']
  return { key: 'litigation', label: 'Litigation exposure', points: q(D(10).minus(deduction)), max: 10, reasons }
}

function iso(p: PartnerRecord, flags: TrustFlag[]): Component {
  const weights: [PartnerRecord['iso_certifications'][number]['standard'], number][] = [['ISO 9001', 6], ['ISO 14001', 4]]
  const factor = { verified: D(1), claimed_unverified: D('0.3'), expired: D('0.15') }
  let points = ZERO
  const reasons: string[] = []
  for (const [standard, weight] of weights) {
    const cert = p.iso_certifications.find((c) => c.standard === standard)
    if (!cert) {
      reasons.push(`${standard}: none (0 pts)`)
      continue
    }
    const earned = D(weight).times(factor[cert.status])
    points = points.plus(earned)
    reasons.push(`${standard}: ${human(cert.status)} (${q1(earned)} pts)`)
    if (cert.status !== 'verified') {
      flags.push({ level: 'info', code: `iso_${standard.slice(4)}_${cert.status}`, message: `${standard} is ${human(cert.status)}.` })
    }
  }
  return { key: 'iso', label: 'ISO quality & environmental certification', points: q(points), max: 10, reasons }
}

function credit(p: PartnerRecord, flags: TrustFlag[]): Component {
  const band = p.credit_rating.band
  const bandPts = D(({ low: 10, moderate: 5 } as Record<string, number>)[band] ?? 0)
  if (band === 'high') flags.push({ level: 'warn', code: 'credit_high_risk', message: `${p.credit_rating.agency}: high credit risk.` })
  else if (band === 'unrated') flags.push({ level: 'warn', code: 'credit_unrated', message: 'No credit rating available.' })
  const solvency = p.financial_solvency_score
  const solvPts = solvency != null ? D(5).times(solvency).div(100) : ZERO
  return {
    key: 'credit', label: 'Creditworthiness', points: q(bandPts.plus(solvPts)), max: 15,
    reasons: [`Credit risk ${band} (${int(bandPts)} pts)`, `Financial solvency ${solvency ?? 'unknown'}/100 (${q1(solvPts)} pts)`],
  }
}

function delivery(p: PartnerRecord, flags: TrustFlag[]): Component {
  const otd = otdTrailing(p)
  const otdPts = D(14).times(scale(otd, D(80), D(98)))
  const acc = p.operations.fulfillment_accuracy_pct
  const accPts = D(6).times(scale(D(acc), D(90), D('99.5')))
  if (otd.lt(90)) flags.push({ level: 'warn', code: 'otd_low', message: `Trailing 12-month on-time delivery ${otd.toFixed(1)}% (< 90%).` })
  return {
    key: 'delivery', label: 'On-time delivery & fulfilment', points: q(otdPts.plus(accPts)), max: 20,
    reasons: [
      `OTD trailing 12 months ${otd.toFixed(1)}% (${q1(otdPts)} pts; full marks at 98%)`,
      `Order fulfilment accuracy ${acc}% (${q1(accPts)} pts; full marks at 99.5%)`,
    ],
  }
}

function crossBorder(p: PartnerRecord, flags: TrustFlag[]): Component {
  const cb = p.cross_border
  const ops = p.operations
  let rate = ZERO
  let sample = ZERO
  if (cb.contracts_total) {
    rate = D(Math.min(cb.contracts_fulfilled, cb.contracts_total)).div(cb.contracts_total)
    sample = Dec.min(ONE, D(cb.contracts_total).div(5))
  } else {
    flags.push({ level: 'info', code: 'no_cross_border', message: 'No verified cross-border contract history.' })
  }
  const contractPts = D(6).times(rate).times(sample).plus(cb.japanese_principals ? ONE : ZERO)
  const retentionPts = D(3).times(scale(D(ops.client_retention_pct), D(60), D(95)))
  const satisfactionPts = D(3).times(scale(D(ops.foreign_principal_satisfaction_pct), D(60), D(95)))
  const slaPts = D(2).times(scale(D(ops.sla_compliance_pct), D(80), D(98)))
  return {
    key: 'cross_border', label: 'Cross-border record & principal satisfaction',
    points: q(contractPts.plus(retentionPts).plus(satisfactionPts).plus(slaPts)), max: 15,
    reasons: [
      `${cb.contracts_fulfilled}/${cb.contracts_total} foreign contracts fulfilled, ${cb.japanese_principals} Japanese principal(s) (${q1(contractPts)} pts)`,
      `Client retention ${ops.client_retention_pct}% (${q1(retentionPts)} pts)`,
      `Foreign principal satisfaction ${ops.foreign_principal_satisfaction_pct}% (${q1(satisfactionPts)} pts)`,
      `Communication SLA compliance ${ops.sla_compliance_pct}% (${q1(slaPts)} pts)`,
    ],
  }
}

function tier(score: Dec, flags: TrustFlag[]): Tier {
  if (flags.some((f) => f.code === 'mca_not_active' || f.code === 'gst_cancelled')) return 'blocked'
  if (flags.some((f) => f.code === 'litigation_major')) return 'not_recommended'
  const t = TIERS.find(([floor]) => score.gte(floor))?.[1] ?? 'not_recommended'
  // A high credit-risk rating keeps the score but never earns the top label.
  if (t === 'japan_ready' && flags.some((f) => f.code === 'credit_high_risk')) return 'conditional'
  return t
}

const LEVEL_ORDER = { block: 0, warn: 1, info: 2 }

export function audit(p: PartnerRecord, now: Date = new Date()): TrustAudit {
  const flags: TrustFlag[] = []
  const components = [mca, gst, litigation, iso, credit, delivery, crossBorder].map((f) => f(p, flags))
  const uncapped = components.reduce((a, c) => a.plus(c.points), ZERO)
  let score = uncapped
  if (flags.some((f) => f.code === 'mca_not_active' || f.code === 'gst_cancelled')) score = q(Dec.min(score, BLOCKED_CAP))
  else if (flags.some((f) => f.code === 'litigation_major')) score = q(Dec.min(score, LITIGATION_CAP))
  const simulated = p.record_source !== 'registry_verified'
  if (simulated) {
    flags.push({ level: 'info', code: 'simulated_record', message: 'Simulated fixture: identifiers and metrics are illustrative, not registry data.' })
  }
  const note = simulated ? ' (simulated record — it will not be found on the portal)' : ''
  return {
    partner_id: p.id,
    partner_name: p.partner_name,
    record_source: p.record_source,
    simulated,
    score: score.toFixed(1),
    uncapped_score: uncapped.toFixed(1),
    tier: tier(score, flags),
    components: components.map((c) => ({ key: c.key, label: c.label, points: c.points.toFixed(1), max_points: String(c.max), reasons: c.reasons })),
    flags: [...flags].sort((a, b) => LEVEL_ORDER[a.level] - LEVEL_ORDER[b.level]),
    otd_trailing_pct: otdTrailing(p).toFixed(1),
    evidence: [
      { label: `MCA company master data · CIN ${p.mca_registration_no}`, url: MCA_PORTAL, note: `Search by CIN${note}` },
      { label: `GST taxpayer search · GSTIN ${p.gstin}`, url: GST_PORTAL, note: `Search by GSTIN${note}` },
    ],
    scoring_version: SCORING_VERSION,
    inputs_hash: inputsHash(p),
    computed_at: now.toISOString(),
    disclosure: DISCLOSURE,
    record: p,
  }
}

export function litigationFlag(p: PartnerRecord): boolean {
  return p.litigation.some((c) => c.status === 'pending' && c.severity === 'major' && (c.case_type === 'tax' || c.case_type === 'corporate'))
}

export type DirectoryFilters = { sector?: Sector; state?: string; minOtd?: string; minTrustScore?: string }

/** Directory items sorted by score (desc) then name, matching the Python service. */
export function directory(records: PartnerRecord[], filters: DirectoryFilters) {
  const state = filters.state?.toLowerCase()
  const items = records
    .filter((r) => (!filters.sector || r.sector === filters.sector) && (!state || r.state.toLowerCase() === state))
    .map((r) => ({ r, a: audit(r) }))
    .filter(({ a }) => !filters.minOtd || D(a.otd_trailing_pct).gte(filters.minOtd))
    .filter(({ a }) => !filters.minTrustScore || D(a.score).gte(filters.minTrustScore))
    .map(({ r, a }) => ({
      id: r.id, partner_name: r.partner_name, record_source: r.record_source, simulated: a.simulated,
      sector: r.sector, state: r.state, city: r.city, partner_type: r.partner_type,
      score: a.score, tier: a.tier, otd_trailing_pct: a.otd_trailing_pct, litigation_flag: litigationFlag(r),
      credit_band: r.credit_rating.band,
      iso_verified: r.iso_certifications.filter((c) => c.status === 'verified').map((c) => c.standard),
      block_flags: a.flags.filter((f) => f.level === 'block').length,
      warn_flags: a.flags.filter((f) => f.level === 'warn').length,
    }))
    .sort((x, y) => D(y.score).cmp(x.score) || (x.partner_name < y.partner_name ? -1 : x.partner_name > y.partner_name ? 1 : 0))
  return {
    partners: items,
    total: items.length,
    filters: { sector: filters.sector ?? null, state: filters.state ?? null, min_otd: filters.minOtd ?? null, min_trust_score: filters.minTrustScore ?? null },
    scoring_version: SCORING_VERSION,
    disclosure: DISCLOSURE,
  }
}
